/* eslint-disable @next/next/no-img-element -- WebP variants are pre-generated by the
   media pipeline and served from /api/media; next/image would add no value here. */
import { cn } from "@/lib/utils";

type MediaImageProps = {
  assetId: string;
  alt: string;
  /** Oriented full-size dimensions (MediaAsset.width/height) — set to reserve space and avoid CLS. */
  width?: number;
  height?: number;
  /** Responsive `sizes` hint; defaults to full viewport width. */
  sizes?: string;
  /** Eager-load + high priority for above-the-fold heroes. */
  priority?: boolean;
  className?: string;
};

/**
 * Renders a media asset via its three pre-generated WebP variants (480/960/1600).
 * The browser picks the best width from `srcSet` + `sizes`; no client JS needed.
 */
export function MediaImage({ assetId, alt, width, height, sizes = "100vw", priority, className }: MediaImageProps) {
  const base = `/api/media/${assetId}`;
  return (
    <img
      src={`${base}/960`}
      srcSet={`${base}/480 480w, ${base}/960 960w, ${base}/1600 1600w`}
      sizes={sizes}
      alt={alt}
      width={width}
      height={height}
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : undefined}
      decoding="async"
      className={cn("h-auto max-w-full", className)}
    />
  );
}
